#include <iostream>
#include <string>
#include <cmath>
#include <algorithm>

// ---- variant selectors (compile-time) ----
#ifndef V_L      // 0:(max+min)/2.0f 1:(max+min)*0.5f 2:double exact (max+min)/2 -> stored float
#define V_L 0
#endif
#ifndef V_BR     // 0: l<0.5f  1: l<=0.5f  2: (max+min)<1.0f  3: double-l < 0.5
#define V_BR 0
#endif
#ifndef V_SH     // high branch denom. 0:(2.0f-max)-min 1:2.0f-(max+min) 2:double 2.0-max-min ->float
#define V_SH 0
#endif
#ifndef V_SL     // low branch denom. 0: (max+min) float  1: double max+min
#define V_SL 0
#endif
#ifndef V_LFIELD // 0: hsl.l is float   1: hsl.l is double holding double result
#define V_LFIELD 0
#endif

static inline float mx3(float r,float g,float b){ float t=(r<g)?g:r; return (t<b)?b:t; }
static inline float mn3(float r,float g,float b){ float t=(g<r)?g:r; return (b<t)?b:t; }

int main(int argc,char**argv){
    float r=0.4f,g=0.2f,b=0.8f;
    if(argc>3){ r=std::stof(argv[1]); g=std::stof(argv[2]); b=std::stof(argv[3]); }
    float mx=mx3(r,g,b), mn=mn3(r,g,b), delta=mx-mn;

    // ---- l ----
#if V_L==0
    float lf=(mx+mn)/2.0f;
#elif V_L==1
    float lf=(mx+mn)*0.5f;
#else
    float lf=(float)(((double)mx+(double)mn)/2.0);
#endif
    double ld=((double)mx+(double)mn)/2.0;

    // ---- hue (established) ----
    float h;
    if(mx==mn) h=0.0f;
    else if(mx==r&&g>=b) h=60.0f*(g-b)/delta;
    else if(mx==r)       h=60.0f*(g-b)/delta+360.0f;
    else if(mx==g)       h=60.0f*(b-r)/delta+120.0f;
    else                 h=60.0f*(r-g)/delta+240.0f;

    // ---- s ----
    float s;
    if(mx==mn) s=0.0f;
    else{
        bool low;
#if V_BR==0
        low = (lf<0.5f);
#elif V_BR==1
        low = (lf<=0.5f);
#elif V_BR==2
        low = ((mx+mn)<1.0f);
#else
        low = (ld<0.5);
#endif
        if(low){
#if V_SL==0
            s=delta/(mx+mn);
#else
            s=(float)((double)delta/((double)mx+(double)mn));
#endif
        } else {
#if V_SH==0
            s=delta/(2.0f-mx-mn);
#elif V_SH==1
            s=delta/(2.0f-(mx+mn));
#else
            s=(float)((double)delta/(2.0-(double)mx-(double)mn));
#endif
        }
    }

    // ---- hsv / cmyk / yuv (established) ----
    float hv=h, vv=mx, sv=(mx==0.0f)?0.0f:delta/mx;
    float k=1.0f-mx, c,m,y;
    if(k==1.0f){c=0.0f;m=0.0f;y=0.0f;}
    else{c=(1.0f-r-k)/(1.0f-k);m=(1.0f-g-k)/(1.0f-k);y=(1.0f-b-k)/(1.0f-k);}
    float yy=((0.299f*r)+(0.587f*g))+(0.114f*b);
    float uu=((-0.147f*r)-(0.289f*g))+(0.436f*b);
    float vy=((0.615f*r)-(0.515f*g))-(0.100f*b);

#if V_LFIELD==0
    float lout=lf;
#else
    double lout=ld;
#endif
    std::cout<<h<<" "<<s<<" "<<lout<<" "
             <<hv<<" "<<sv<<" "<<vv<<" "
             <<c<<" "<<m<<" "<<y<<" "<<k<<" "
             <<yy<<" "<<uu<<" "<<vy<<std::endl;
    return 0;
}
EOF
