#include <cstdio>
#include <cstdint>
#include <cstring>
#include <cmath>
#include <string>
#include <vector>
#include <set>
#include <random>
using namespace std;

static uint64_t st=0x12345678abcdefULL;
static uint64_t nx(){ st^=st<<13; st^=st>>7; st^=st<<17; return st; }
static double ur(){ return (double)(nx()>>11)/9007199254740992.0; }

static string p9(float v){ char b[64];
  if(std::isnan(v)) return std::signbit(v)?string("-nan"):string("nan");
  if(std::isinf(v)) return std::signbit(v)?string("-inf"):string("inf");
  snprintf(b,sizeof b,"%.9g",(double)v); return string(b); }
static string p6(double v){ char b[64]; snprintf(b,sizeof b,"%.6g",v); return string(b); }

static bool okf(float v){ if(!std::isfinite(v)) return false; if(v==0) return true;
  float a=fabsf(v); return a>=1e-30f && a<=1e30f; }

static vector<string> out;
static set<string> seen;
static void emit(float r,float g,float b){
  if(!okf(r)||!okf(g)||!okf(b)) return;
  string s=p9(r)+" "+p9(g)+" "+p9(b);
  if(seen.insert(s).second) out.push_back(s);
}
static void emitRaw(const char*a,const char*b,const char*c){
  string s=string(a)+" "+b+" "+c; if(seen.insert(s).second) out.push_back(s);
}
static float ulpstep(float v,int k){ if(v==0) return v; int32_t i; memcpy(&i,&v,4); i+=k; float o; memcpy(&o,&i,4); return o; }

// float ops
static inline float FL(double d){ return (float)d; }

int main(){
  // ---------- 1. specials ----------
  const char* sp[]={"inf","-inf","nan","-nan","0","-0","1","-1","0.5","2","-2","1e-30","-1e-30","3.4e38","-3.4e38"};
  int ns=sizeof(sp)/sizeof(*sp);
  for(int i=0;i<ns;i++)for(int j=0;j<ns;j++)for(int k=0;k<ns;k++) emitRaw(sp[i],sp[j],sp[k]);

  // ---------- 2. uniform random in [-2,2] ----------
  for(int i=0;i<9000;i++) emit((float)(ur()*4-2),(float)(ur()*4-2),(float)(ur()*4-2));
  // ---------- 2b. uniform in [0,1] (natural domain) ----------
  for(int i=0;i<7000;i++) emit((float)ur(),(float)ur(),(float)ur());
  // ---------- 3. random bit patterns (normal, bounded exponent) ----------
  for(int i=0;i<7000;i++){
    float v[3];
    for(int j=0;j<3;j++){ uint32_t u=(uint32_t)nx(); int e=(int)(nx()%80)+87; // exp field 87..166 -> ~1e-12..1e12
      u=(u&0x807FFFFFu)|((uint32_t)e<<23); memcpy(&v[j],&u,4); }
    emit(v[0],v[1],v[2]);
  }

  // ---------- 4. max+min near 1  (branch boundary), many ulp offsets ----------
  for(int i=0;i<9000;i++){
    float a=(float)(0.2+ur()*1.3);
    float bt=(float)(1.0-(double)a);
    int k=(int)(nx()%13)-6;
    float bb=ulpstep(bt,k);
    // ensure a>=bb ordering variants; third value in between or outside
    float lo=fminf(a,bb), hi=fmaxf(a,bb);
    float mid=(float)(lo+ur()*((double)hi-(double)lo));
    int perm=(int)(nx()%6);
    float t[3]={hi,mid,lo};
    if(perm==1){t[0]=hi;t[1]=lo;t[2]=mid;}
    if(perm==2){t[0]=mid;t[1]=hi;t[2]=lo;}
    if(perm==3){t[0]=mid;t[1]=lo;t[2]=hi;}
    if(perm==4){t[0]=lo;t[1]=hi;t[2]=mid;}
    if(perm==5){t[0]=lo;t[1]=mid;t[2]=hi;}
    emit(t[0],t[1],t[2]);
    emit(hi,lo,lo); emit(hi,hi,lo);
  }
  // exact boundary constructions: S in [1-2^-25,1) and neighbours
  {
    float cands[]={1.0f,1.0f-ldexpf(1,-24),1.0f-ldexpf(1,-23),0.875f,0.75f,0.5f,1.25f,1.5f,1.0f+ldexpf(1,-23)};
    for(float mxv:cands) for(int k=-8;k<=8;k++){
      float mnv=ulpstep((float)(1.0-(double)mxv),k);
      if(mnv>mxv) continue;
      emit(mxv,mnv,mnv); emit(mxv,mxv,mnv); emit(mxv,mnv,mxv);
    }
    // fine sub-ulp sums: max in [0.5,1) (ulp 2^-24) with tiny min
    for(int j=1;j<=40;j++) for(int k=-4;k<=4;k++){
      float mxv=1.0f-ldexpf(1,-24)*j;
      float mnv=ldexpf(1,-24)*j+ldexpf(1,-25)*k;
      if(mnv>mxv||mnv==0) continue;
      emit(mxv,mnv,mnv);
    }
    for(int j=0;j<60;j++) for(int k=-30;k<=30;k++){
      float mxv=0.875f+ldexpf(1,-24)*j;
      float mnv=0.125f+ldexpf(1,-27)*k;
      if(mnv>mxv) continue;
      emit(mxv,mnv,mnv);
    }
  }

  // ---------- 5. targeted: 6th-sig-digit sensitivity of l (float vs exact) ----------
  {int got=0;
   for(long i=0;i<40000000L&&got<3000;i++){
     float a,bb;
     {uint32_t u=(uint32_t)nx(); int e=(int)(nx()%30)+113; u=(u&0x807FFFFFu)|((uint32_t)e<<23); memcpy(&a,&u,4);} 
     {uint32_t u=(uint32_t)nx(); int e=(int)(nx()%30)+113; u=(u&0x807FFFFFu)|((uint32_t)e<<23); memcpy(&bb,&u,4);} 
     if(!okf(a)||!okf(bb)) continue;
     double S=(double)a+(double)bb; float Sf=(float)a+(float)bb;
     if((double)Sf==S) continue;
     float lf=Sf/2.0f; double ld=S/2.0;
     if(p6((double)lf)!=p6(ld)){ float hi=fmaxf(a,bb),lo=fminf(a,bb); emit(hi,lo,lo); got++; }
   }
   fprintf(stderr,"l-discriminators: %d\n",got);}

  // ---------- 6. targeted: high-branch denominator variants differ in printed s ----------
  {int got=0;
   for(long i=0;i<60000000L&&got<3000;i++){
     float mxv,mnv;
     {uint32_t u=(uint32_t)nx(); int e=(int)(nx()%14)+119; u=(u&0x807FFFFFu)|((uint32_t)e<<23); memcpy(&mxv,&u,4);} 
     {uint32_t u=(uint32_t)nx(); int e=(int)(nx()%14)+119; u=(u&0x807FFFFFu)|((uint32_t)e<<23); memcpy(&mnv,&u,4);} 
     if(mnv>mxv){float t=mxv;mxv=mnv;mnv=t;}
     if(!okf(mxv)||!okf(mnv)) continue;
     float Sf=mxv+mnv; if(!(Sf>=1.0f)) continue;   // high branch
     float d=mxv-mnv;
     float d0=(2.0f-mxv)-mnv;
     float d1=2.0f-Sf;
     float d2=(float)(2.0-(double)mxv-(double)mnv);
     float s0=d/d0,s1=d/d1,s2=d/d2;
     if(p6(s0)!=p6(s1)||p6(s0)!=p6(s2)){ emit(mxv,mnv,mnv); got++; }
   }
   fprintf(stderr,"sh-discriminators: %d\n",got);}

  // ---------- 7. targeted: low-branch s float vs double ----------
  {int got=0;
   for(long i=0;i<60000000L&&got<3000;i++){
     float mxv,mnv;
     {uint32_t u=(uint32_t)nx(); int e=(int)(nx()%40)+108; u=(u&0x807FFFFFu)|((uint32_t)e<<23); memcpy(&mxv,&u,4);} 
     {uint32_t u=(uint32_t)nx(); int e=(int)(nx()%40)+108; u=(u&0x807FFFFFu)|((uint32_t)e<<23); memcpy(&mnv,&u,4);} 
     if(mnv>mxv){float t=mxv;mxv=mnv;mnv=t;}
     if(!okf(mxv)||!okf(mnv)) continue;
     float Sf=mxv+mnv; if(!(Sf<1.0f)) continue;   // low branch
     float d=mxv-mnv;
     float s0=d/Sf;
     float s1=(float)((double)d/((double)mxv+(double)mnv));
     if(p6(s0)!=p6(s1)){ emit(mxv,mnv,mnv); got++; }
   }
   fprintf(stderr,"sl-discriminators: %d\n",got);}

  // ---------- 8. targeted: branch predicate disagreement float-l vs double-l ----------
  {int got=0;
   // S in [1-2^-25, 1): fl(S)==1 but S<1
   for(long i=0;i<80000000L&&got<2000;i++){
     float mxv;
     {uint32_t u=(uint32_t)nx(); int e=(int)(nx()%6)+124; u=(u&0x007FFFFFu)|((uint32_t)e<<23); memcpy(&mxv,&u,4);} 
     if(!(mxv>0)) continue;
     // choose mnv near 1-mxv, scan ulps
     float bt=(float)(1.0-(double)mxv);
     for(int k=-6;k<=6;k++){
       float mnv=ulpstep(bt,k);
       if(mnv>mxv||!okf(mnv)) continue;
       double S=(double)mxv+(double)mnv; float Sf=mxv+mnv;
       bool lowF=(Sf/2.0f)<0.5f, lowD=(S/2.0)<0.5, lowS=(Sf<1.0f);
       if(lowF!=lowD||lowF!=lowS){ emit(mxv,mnv,mnv); emit(mxv,mxv,mnv); got++; }
     }
   }
   fprintf(stderr,"branch-discriminators: %d\n",got);}
  // brute force small-scale exact straddles
  for(int ea=-3;ea<=1;ea++) for(int j=0;j<2000;j++){
    float mxv=ldexpf(1.0f,ea)*(1.0f+(float)ur());
    float bt=(float)(1.0-(double)mxv);
    for(int k=-3;k<=3;k++){ float mnv=ulpstep(bt,k); if(mnv<=mxv&&okf(mnv)) emit(mxv,mnv,mnv); }
  }

  // ---------- 9. equal / near-equal, zeros, sign zeros ----------
  for(int i=0;i<1500;i++){ float a=(float)(ur()*2-1); emit(a,a,a); emit(a,a,ulpstep(a,1)); emit(a,ulpstep(a,-1),a); }
  for(int i=0;i<800;i++){ float a=(float)(ur()*2); emit(a,-a,0.0f); emit(a,-a,a); emit(-0.0f,a,-a); }

  for(auto&s:out) printf("%s\n",s.c_str());
  fprintf(stderr,"TOTAL %zu\n",out.size());
  return 0;
}
