#include <iostream>
#include <cmath>
static inline float mx3(float r,float g,float b){ float t=(r<g)?g:r; return (t<b)?b:t; }
static inline float mn3(float r,float g,float b){ float t=(g<r)?g:r; return (b<t)?b:t; }
int main(int argc,char**argv){
    float r=0.4f,g=0.2f,b=0.8f;
    if(argc>3){ r=std::stof(argv[1]); g=std::stof(argv[2]); b=std::stof(argv[3]); }
    volatile float vmx=mx3(r,g,b), vmn=mn3(r,g,b);
    float mx=vmx, mn=vmn, delta=mx-mn, Sf=mx+mn;
    // --- l variants (7) ---
    float L[7];
    L[0]=Sf/2.0f;
    L[1]=Sf*0.5f;
    L[2]=mx/2.0f+mn/2.0f;
    L[3]=mn+(mx-mn)/2.0f;
    L[4]=mn+delta/2.0f;
    L[5]=(float)(((double)mx+(double)mn)/2.0);
    L[6]=(mn+mx)/2.0f;
